frame.store("_the_card_that_places_the_figure", { let __signature_486 = Signature { name: "_the_card_that_places_the_figure".into(), positional: vec!["candidates".into(),"best".into(),"text".into(),"memory".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_488 = Value::dict(); __attrs_488.dict_set(Value::from("__doc__"), Value::from("A card that puts the figure against a range beats the composer's ask for a second figure.\n\n    The operator's rule: the reply that fits the line most closely wins, and a broad \"\n    what are you comparing it with\" is beaten by the one that says what the figure is like. The\n    hand-back is still the answer when no card has a range - that is the whole point of it - so\n    this only moves the turn when a candidate both names what the line is about and carries a\n    figure (`_places_the_figure`).\n    "))?; __attrs_488.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_489 = Value::dict(); __attrs_488.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_485 = Frame::module(frame.globals.clone()); let mut __function_487 = NativeFunction::qualified_with_origin("_the_card_that_places_the_figure".into(), "_the_card_that_places_the_figure".into(), "bot.modules.arbiter".into(), __attrs_488, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/arbiter.py", first: 1673, last: 1690, qualname: "_the_card_that_places_the_figure" }, closure: __closure_485.clone(), freevars: vec![] }, move |rt, args| __py_39::_the_card_that_places_the_figure(rt, __closure_485.clone(), &__signature_486, args)); __function_487 })?;
