let __v_518 = { let __callable_519 = frame.load(rt, "frozenset")?; let mut __args_520 = CallArgs::default(); let __v_521 = { let __callable_522 = { let __v_524 = Value::from("a an the and or but if of to in on at for with from by as it\nits this that these those i me my we us our you your he she they them their not no yes so then than\njust also very really quite some any all about there here out up down over under more most much\nless"); rt.getattr(&__v_524, "split")? }; let mut __args_523 = CallArgs::default(); rt.call(&__callable_522, __args_523)? }; __args_520.positional.push(__v_521); rt.call(&__callable_519, __args_520)? };
