frame.store("_an_answer_behind_the_ask", { let __signature_601 = Signature { name: "_an_answer_behind_the_ask".into(), positional: vec!["memory".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_603 = Value::dict(); __attrs_603.dict_set(Value::from("__doc__"), Value::from("Whether the last thing the bot said is an answer, so a repeat ask has one to hand back.\n\n    A repeat ask is the answer again, and this file holds the turn for it. Where the bot's last\n    line was a nod - \"that thing you said about the boiler\", \"sorry i lost it\", \"can you say it\n    again\" - there is no answer to say again: the store hands back \"Ugh, that's a lot to carry.\"\n    and the arbiter, told the line is a repeat, passes over the card that did read it. Saying a\n    nod twice answers nothing, so a nod is not an answer behind the ask.\n    "))?; __attrs_603.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_604 = Value::dict(); __attrs_603.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_600 = Frame::module(frame.globals.clone()); let mut __function_602 = NativeFunction::qualified_with_origin("_an_answer_behind_the_ask".into(), "_an_answer_behind_the_ask".into(), "bot.modules.arbiter".into(), __attrs_603, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/arbiter.py", first: 2072, last: 2087, qualname: "_an_answer_behind_the_ask" }, closure: __closure_600.clone(), freevars: vec![] }, move |rt, args| __py_50::_an_answer_behind_the_ask(rt, __closure_600.clone(), &__signature_601, args)); __function_602 })?;
