frame.store("_pause_reply", { let __default_1115 = Value::from(""); let __signature_1113 = Signature { name: "_pause_reply".into(), positional: vec!["candidates".into(),"pool".into(),"text".into(),"memory".into(),"last".into()], positional_only: 0, defaults: vec![__default_1115], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1116 = Value::dict(); __attrs_1116.dict_set(Value::from("__doc__"), Value::from("The index of the composer's line for an apology about the chat pausing, or None.\n\n    \"sorry for not replying\" is an apology for the gap and nothing else, and a topic entry can\n    still take it on a word of it: the answers module read \"reply\" and \"message\" as a request\n    to draft an email, so a person who had just said sorry for being away was told to \"say the\n    ask in the first line\". The reading and the wording are the composer's\n    (`fallback.reads_as_pause`, `fallback.CAME_BACK`); the arbiter only keeps the turn where it\n    belongs, the way it does for a goodbye.\n\n    Not at the expense of a module that read the whole line itself: the loss and grief bands sit\n    above `WHOLE_LINE_BAND` and their turn stands, and a safety thread was answered before this\n    (`_composer_reading` returns THREAD for it, so there is no pause to keep).\n    "))?; __attrs_1116.dict_set(Value::from("__defaults__"), Value::tuple(__signature_1113.defaults.clone()))?; let __kwdefaults_1117 = Value::dict(); __attrs_1116.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1112 = Frame::module(frame.globals.clone()); let mut __function_1114 = NativeFunction::qualified_with_origin("_pause_reply".into(), "_pause_reply".into(), "bot.modules.arbiter".into(), __attrs_1116, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/arbiter.py", first: 4060, last: 4103, qualname: "_pause_reply" }, closure: __closure_1112.clone(), freevars: vec![] }, move |rt, args| __py_122::_pause_reply(rt, __closure_1112.clone(), &__signature_1113, args)); __function_1114 })?;
frame.store("_leaving_reply", { let __default_1121 = Value::from(""); let __signature_1119 = Signature { name: "_leaving_reply".into(), positional: vec!["candidates".into(),"own".into(),"carried".into(),"words".into(),"clean".into(),"text".into(),"memory".into(),"last".into()], positional_only: 0, defaults: vec![__default_1121], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1122 = Value::dict(); __attrs_1122.dict_set(Value::from("__doc__"), Value::from("The index of the sign-off for a line that says the person is going, or None.\n\n    A goodbye is the one line no topic entry owns, and every topic entry can win it on a word of\n    the reason behind it: \"ill let you go, dinner is burning\" matched cooking, \"better go and\n    get the washing in\" got the search shrug, \"got to go, the kids are up\" got a nod. The\n    reading and the wording are the composer's (bot/compose/leaving.py); the arbiter only keeps\n    the turn where it belongs. A leave inside a safety thread is still that thread, so the\n    careful continuation keeps it.\n    "))?; __attrs_1122.dict_set(Value::from("__defaults__"), Value::tuple(__signature_1119.defaults.clone()))?; let __kwdefaults_1123 = Value::dict(); __attrs_1122.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1118 = Frame::module(frame.globals.clone()); let mut __function_1120 = NativeFunction::qualified_with_origin("_leaving_reply".into(), "_leaving_reply".into(), "bot.modules.arbiter".into(), __attrs_1122, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/arbiter.py", first: 4106, last: 4167, qualname: "_leaving_reply" }, closure: __closure_1118.clone(), freevars: vec![] }, move |rt, args| __py_123::_leaving_reply(rt, __closure_1118.clone(), &__signature_1119, args)); __function_1120 })?;
