frame.store("_about_the_person_the_line_names", { let __default_1230 = Value::from(""); let __signature_1228 = Signature { name: "_about_the_person_the_line_names".into(), positional: vec!["candidates".into(),"pool".into(),"clean".into(),"last".into()], positional_only: 0, defaults: vec![__default_1230], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_1231 = Value::dict(); __attrs_1231.dict_set(Value::from("__doc__"), Value::from("The index of a reply about the person a how-to line names, when the front one is not.\n\n    The card in front answers the speaker's own life; the entry below it answers the question\n    about the other person. Read only on a how-to line that names someone (\"how do i stop my\n    teenager staying up all night\"), so a line about the speaker is untouched. The person the\n    how-to is about is the first person the line names, so \"how do i console a friend whos just\n    lost their dad\" is about the friend and their grief, not a cue to answer about a dad. And a\n    reply that says it cannot answer is never taken over the card in front, which can.\n    "))?; __attrs_1231.dict_set(Value::from("__defaults__"), Value::tuple(__signature_1228.defaults.clone()))?; let __kwdefaults_1232 = Value::dict(); __attrs_1231.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_1227 = Frame::module(frame.globals.clone()); let mut __function_1229 = NativeFunction::qualified_with_origin("_about_the_person_the_line_names".into(), "_about_the_person_the_line_names".into(), "bot.modules.arbiter".into(), __attrs_1231, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/modules/arbiter.py", first: 4554, last: 4594, qualname: "_about_the_person_the_line_names" }, closure: __closure_1227.clone(), freevars: vec![] }, move |rt, args| __py_138::_about_the_person_the_line_names(rt, __closure_1227.clone(), &__signature_1228, args)); __function_1229 })?;
